241	            Ok(mut s) => {
242	                let _ = s.set_read_timeout(Some(Duration::from_millis(50)));
243	                let _ = s.set_nodelay(true);
244	                send(Event::Status(Status::Connected));
245	                send(Event::Log(LogKind::Ok, "Connected to the fan.".into()));
246	                let mut buf = [0u8; 1024];
247	                loop {
248	                    match rx.recv_timeout(Duration::from_millis(100)) {
249	                        Ok(Cmd::Upload(files)) => {
250	                            if let Err(e) = send_files(&mut s, &files, &send) {
251	                                send(Event::Log(LogKind::Warn, format!("Upload failed: {e}")));
252	                            }
253	                            send(Event::Progress(None));
254	                        }
