256	                            let line = format!("{}\n", cmd.wire());
257	                            if let Err(e) = s.write_all(line.as_bytes()) {
258	                                send(Event::Log(LogKind::Warn, format!("Connection lost: {e}")));
259	                                break;
260	                            }
261	                        }
262	                        Err(RecvTimeoutError::Timeout) => {}
