264	                    }
265	                    match s.read(&mut buf) {
266	                        Ok(0) => {
267	                            send(Event::Log(LogKind::Warn, "The fan closed the connection.".into()));
268	                            break;
269	                        }
270	                        Ok(n) => {
271	                            let text = String::from_utf8_lossy(&buf[..n]).trim().to_string();
272	                            if !text.is_empty() {
273	                                send(Event::Log(LogKind::Fan, text));
274	                            }
275	                        }
276	                        Err(_) => {} // timeout: nothing to read
277	                    }
278	                }
279	            }
