// Connection to the hologram fan over its Wi-Fi network.
//
// IMPORTANT: the fan's real protocol isn't known (the original program was never looked inside).
// Commands are sent as simple text lines over TCP ("PLAY_PAUSE\n", ...) to an address the person
// can change on the Device page. Once the real protocol is known, only `Cmd::wire` and
// `send_file` need to change.

use std::io::{Read, Write};
use std::net::{TcpStream, ToSocketAddrs};
use std::path::PathBuf;
use std::sync::mpsc::{Receiver, RecvTimeoutError, Sender, channel};
use std::thread;
use std::time::{Duration, Instant};

use eframe::egui;

#[derive(Clone, Debug)]
pub enum Cmd {
    Prev,
    Next,
    PlayPause,
    SingleLoop,
    ListLoop,
    Power,
    FormatDisk,
    ClearCache,
    BrightnessUp,
    BrightnessDown,
    RotateCw,
    RotateCcw,
    Clock { on: bool, needle_white: bool, dial: &'static str },
    PowerOnTime { h: u32, m: u32, s: u32 },
    PictureTime(u32),
    Wifi { ssid: String, password: String },
    Model(String),
    Upload(Vec<PathBuf>),
}

impl Cmd {
    pub fn label(&self) -> String {
        match self {
            Cmd::Prev => "Previous".into(),
            Cmd::Next => "Next".into(),
            Cmd::PlayPause => "Play / pause".into(),
            Cmd::SingleLoop => "Single loop".into(),
            Cmd::ListLoop => "List loop".into(),
            Cmd::Power => "Power on/off".into(),
            Cmd::FormatDisk => "Format fan storage".into(),
            Cmd::ClearCache => "Clear cache".into(),
            Cmd::BrightnessUp => "Brightness +".into(),
            Cmd::BrightnessDown => "Brightness −".into(),
            Cmd::RotateCw => "Rotate clockwise".into(),
            Cmd::RotateCcw => "Rotate counter-clockwise".into(),
            Cmd::Clock { .. } => "Clock settings".into(),
            Cmd::PowerOnTime { .. } => "Power-on display time".into(),
            Cmd::PictureTime(_) => "Picture play time".into(),
            Cmd::Wifi { .. } => "Wi-Fi settings".into(),
            Cmd::Model(_) => "Fan model".into(),
            Cmd::Upload(f) => format!("Upload {} file(s)", f.len()),
        }
    }

    /// Text sent to the fan (placeholder protocol, see the note at the top).
    fn wire(&self) -> String {
        match self {
            Cmd::Prev => "PREV".into(),
            Cmd::Next => "NEXT".into(),
            Cmd::PlayPause => "PLAY_PAUSE".into(),
            Cmd::SingleLoop => "LOOP SINGLE".into(),
            Cmd::ListLoop => "LOOP LIST".into(),
            Cmd::Power => "POWER".into(),
            Cmd::FormatDisk => "FORMAT".into(),
            Cmd::ClearCache => "CLEAR_CACHE".into(),
            Cmd::BrightnessUp => "BRIGHTNESS +".into(),
            Cmd::BrightnessDown => "BRIGHTNESS -".into(),
            Cmd::RotateCw => "ROTATE CW".into(),
            Cmd::RotateCcw => "ROTATE CCW".into(),
            Cmd::Clock { on, needle_white, dial } => format!(
                "CLOCK {} NEEDLE {} DIAL {}",
                if *on { "ON" } else { "OFF" },
                if *needle_white { "WHITE" } else { "BLACK" },
                dial.to_uppercase()
            ),
            Cmd::PowerOnTime { h, m, s } => format!("BOOT_TIME {h:02}:{m:02}:{s:02}"),
            Cmd::PictureTime(s) => format!("PICTURE_TIME {s}"),
            Cmd::Wifi { ssid, password } => format!("WIFI \"{ssid}\" \"{password}\""),
            Cmd::Model(m) => format!("MODEL {m}"),
            Cmd::Upload(_) => String::new(),
        }
    }
}

#[derive(Clone, PartialEq, Debug)]
pub enum Status {
    Disconnected,
    Connecting,
    Connected,
    Failed,
}

#[derive(Clone, Copy, PartialEq)]
pub enum LogKind {
    Info,
    Ok,
    Warn,
    Sent,
    Fan,
}

pub struct LogLine {
    pub time: String,
    pub kind: LogKind,
    pub text: String,
}

enum Event {
    Status(Status),
    Log(LogKind, String),
    Progress(Option<f32>),
}

pub struct Device {
    pub status: Status,
    pub log: Vec<LogLine>,
    pub upload_progress: Option<f32>,
    pub address: String,
    cmd_tx: Option<Sender<Cmd>>,
    evt_tx: Sender<Event>,
    evt_rx: Receiver<Event>,
    started: Instant,
}

impl Device {
    pub fn new(address: String) -> Self {
        let (evt_tx, evt_rx) = channel();
        Self {
            status: Status::Disconnected,
            log: Vec::new(),
            upload_progress: None,
            address,
            cmd_tx: None,
            evt_tx,
            evt_rx,
            started: Instant::now(),
        }
    }

    pub fn is_connected(&self) -> bool {
        self.status == Status::Connected
    }

    pub fn is_active(&self) -> bool {
        self.cmd_tx.is_some()
    }

    pub fn push_log(&mut self, kind: LogKind, text: impl Into<String>) {
        let t = self.started.elapsed().as_secs();
        self.log.push(LogLine {
            time: format!("{:02}:{:02}:{:02}", t / 3600, (t / 60) % 60, t % 60),
            kind,
            text: text.into(),
        });
        if self.log.len() > 500 {
            self.log.drain(0..100);
        }
    }

    /// Start connecting (keeps retrying every few seconds until `disconnect`).
    pub fn connect(&mut self, ctx: &egui::Context) {
        self.disconnect();
        let (cmd_tx, cmd_rx) = channel();
        self.cmd_tx = Some(cmd_tx);
        self.status = Status::Connecting;
        let addr = self.address.clone();
        let tx = self.evt_tx.clone();
        let ctx = ctx.clone();
        thread::spawn(move || worker(addr, cmd_rx, tx, ctx));
    }

    pub fn disconnect(&mut self) {
        if self.cmd_tx.take().is_some() {
            self.push_log(LogKind::Info, "Disconnected from the fan.");
        }
        self.status = Status::Disconnected;
        self.upload_progress = None;
    }

    /// Send a command; when there is no connection it is only logged.
    pub fn send(&mut self, cmd: Cmd) -> bool {
        if !self.is_connected() {
            self.push_log(LogKind::Warn, format!("Not connected — “{}” was not sent.", cmd.label()));
            return false;
        }
        let label = cmd.label();
        if let Some(tx) = &self.cmd_tx {
            if tx.send(cmd).is_ok() {
                self.push_log(LogKind::Sent, label);
                return true;
            }
        }
        false
    }

    pub fn poll(&mut self) {
        while let Ok(e) = self.evt_rx.try_recv() {
            match e {
                Event::Status(s) => {
                    // ignore late messages from a worker that was already stopped
                    if self.cmd_tx.is_some() {
                        self.status = s;
                    }
                }
                Event::Log(k, t) => {
                    if self.cmd_tx.is_some() {
                        self.push_log(k, t);
                    }
                }
                Event::Progress(p) => self.upload_progress = p,
            }
        }
    }
}

fn worker(addr: String, rx: Receiver<Cmd>, tx: Sender<Event>, ctx: egui::Context) {
    let send = |e: Event| {
        let ok = tx.send(e).is_ok();
        ctx.request_repaint();
        ok
    };
    loop {
        send(Event::Status(Status::Connecting));
        if !send(Event::Log(LogKind::Info, format!("Trying to connect to the fan's network at {addr}…"))) {
            return;
        }
        let target = addr.to_socket_addrs().ok().and_then(|mut a| a.next());
        let stream = match target {
            Some(sa) => TcpStream::connect_timeout(&sa, Duration::from_secs(3)).map_err(|e| e.to_string()),
            None => Err("the address is not valid".to_string()),
        };
        match stream {
            Ok(mut s) => {
                let _ = s.set_read_timeout(Some(Duration::from_millis(50)));
                let _ = s.set_nodelay(true);
                send(Event::Status(Status::Connected));
                send(Event::Log(LogKind::Ok, "Connected to the fan.".into()));
                let mut buf = [0u8; 1024];
                loop {
                    match rx.recv_timeout(Duration::from_millis(100)) {
                        Ok(Cmd::Upload(files)) => {
                            if let Err(e) = send_files(&mut s, &files, &send) {
                                send(Event::Log(LogKind::Warn, format!("Upload failed: {e}")));
                            }
                            send(Event::Progress(None));
                        }
                        Ok(cmd) => {
                            let line = format!("{}\n", cmd.wire());
                            if let Err(e) = s.write_all(line.as_bytes()) {
                                send(Event::Log(LogKind::Warn, format!("Connection lost: {e}")));
                                break;
                            }
                        }
                        Err(RecvTimeoutError::Timeout) => {}
                        Err(RecvTimeoutError::Disconnected) => return,
                    }
                    match s.read(&mut buf) {
                        Ok(0) => {
                            send(Event::Log(LogKind::Warn, "The fan closed the connection.".into()));
                            break;
                        }
                        Ok(n) => {
                            let text = String::from_utf8_lossy(&buf[..n]).trim().to_string();
                            if !text.is_empty() {
                                send(Event::Log(LogKind::Fan, text));
                            }
                        }
                        Err(_) => {} // timeout: nothing to read
                    }
                }
            }
            Err(e) => {
                send(Event::Status(Status::Failed));
                send(Event::Log(LogKind::Warn, format!("No answer from the fan ({e}). Retrying in 5 seconds.")));
            }
        }
        // wait before retrying, but stop at once when disconnected
        let until = Instant::now() + Duration::from_secs(5);
        while Instant::now() < until {
            match rx.recv_timeout(Duration::from_millis(200)) {
                Err(RecvTimeoutError::Disconnected) => return,
                _ => {}
            }
        }
    }
}

fn send_files(s: &mut TcpStream, files: &[PathBuf], send: &dyn Fn(Event) -> bool) -> std::io::Result<()> {
    let total: u64 = files.iter().filter_map(|f| std::fs::metadata(f).ok()).map(|m| m.len()).sum::<u64>().max(1);
    let mut done = 0u64;
    for f in files {
        let name = f.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
        let mut file = std::fs::File::open(f)?;
        let len = file.metadata()?.len();
        s.write_all(format!("UPLOAD \"{name}\" {len}\n").as_bytes())?;
        let mut buf = vec![0u8; 64 * 1024];
        loop {
            let n = file.read(&mut buf)?;
            if n == 0 {
                break;
            }
            s.write_all(&buf[..n])?;
            done += n as u64;
            send(Event::Progress(Some(done as f32 / total as f32)));
        }
        send(Event::Log(LogKind::Ok, format!("Uploaded {name}")));
    }
    Ok(())
}

