101	#[derive(Clone, Copy, PartialEq)]
102	pub enum LogKind {
103	    Info,
104	    Ok,
105	    Warn,
106	    Sent,
107	    Fan,
108	}
109	
110	pub struct LogLine {
111	    pub time: String,
112	    pub kind: LogKind,
113	    pub text: String,
114	}
115	
116	enum Event {
117	    Status(Status),
118	    Log(LogKind, String),
119	    Progress(Option<f32>),
120	}
121	
122	pub struct Device {
123	    pub status: Status,
124	    pub log: Vec<LogLine>,
125	    pub upload_progress: Option<f32>,
126	    pub address: String,
127	    cmd_tx: Option<Sender<Cmd>>,
128	    evt_tx: Sender<Event>,
129	    evt_rx: Receiver<Event>,
130	    started: Instant,
131	}
132	
133	impl Device {
134	    pub fn new(address: String) -> Self {
135	        let (evt_tx, evt_rx) = channel();
136	        Self {
137	            status: Status::Disconnected,
138	            log: Vec::new(),
139	            upload_progress: None,
140	            address,
141	            cmd_tx: None,
142	            evt_tx,
143	            evt_rx,
144	            started: Instant::now(),
145	        }
146	    }
147	
148	    pub fn is_connected(&self) -> bool {
149	        self.status == Status::Connected
150	    }
151	
152	    pub fn is_active(&self) -> bool {
153	        self.cmd_tx.is_some()
154	    }
155	
156	    pub fn push_log(&mut self, kind: LogKind, text: impl Into<String>) {
157	        let t = self.started.elapsed().as_secs();
158	        self.log.push(LogLine {
159	            time: format!("{:02}:{:02}:{:02}", t / 3600, (t / 60) % 60, t % 60),
160	            kind,
161	            text: text.into(),
162	        });
163	        if self.log.len() > 500 {
164	            self.log.drain(0..100);
165	        }
166	    }
167	
168	    /// Start connecting (keeps retrying every few seconds until `disconnect`).
169	    pub fn connect(&mut self, ctx: &egui::Context) {
170	        self.disconnect();
171	        let (cmd_tx, cmd_rx) = channel();
172	        self.cmd_tx = Some(cmd_tx);
173	        self.status = Status::Connecting;
174	        let addr = self.address.clone();
175	        let tx = self.evt_tx.clone();
176	        let ctx = ctx.clone();
177	        thread::spawn(move || worker(addr, cmd_rx, tx, ctx));
178	    }
179	
180	    pub fn disconnect(&mut self) {
181	        if self.cmd_tx.take().is_some() {
182	            self.push_log(LogKind::Info, "Disconnected from the fan.");
183	        }
184	        self.status = Status::Disconnected;
185	        self.upload_progress = None;
186	    }
187	
188	    /// Send a command; when there is no connection it is only logged.
189	    pub fn send(&mut self, cmd: Cmd) -> bool {
190	        if !self.is_connected() {
191	            self.push_log(LogKind::Warn, format!("Not connected — “{}” was not sent.", cmd.label()));
192	            return false;
193	        }
194	        let label = cmd.label();
195	        if let Some(tx) = &self.cmd_tx {
196	            if tx.send(cmd).is_ok() {
197	                self.push_log(LogKind::Sent, label);
198	                return true;
199	            }
200	        }
201	        false
202	    }
203	
204	    pub fn poll(&mut self) {
205	        while let Ok(e) = self.evt_rx.try_recv() {
206	            match e {
207	                Event::Status(s) => {
208	                    // ignore late messages from a worker that was already stopped
209	                    if self.cmd_tx.is_some() {
210	                        self.status = s;
211	                    }
212	                }
213	                Event::Log(k, t) => {
214	                    if self.cmd_tx.is_some() {
215	                        self.push_log(k, t);
216	                    }
217	                }
218	                Event::Progress(p) => self.upload_progress = p,
219	            }
220	        }
221	    }
222	}
223	
224	fn worker(addr: String, rx: Receiver<Cmd>, tx: Sender<Event>, ctx: egui::Context) {
225	    let send = |e: Event| {
226	        let ok = tx.send(e).is_ok();
227	        ctx.request_repaint();
228	        ok
229	    };
230	    loop {
231	        send(Event::Status(Status::Connecting));
232	        if !send(Event::Log(LogKind::Info, format!("Trying to connect to the fan's network at {addr}…"))) {
233	            return;
234	        }
235	        let target = addr.to_socket_addrs().ok().and_then(|mut a| a.next());
236	        let stream = match target {
237	            Some(sa) => TcpStream::connect_timeout(&sa, Duration::from_secs(3)).map_err(|e| e.to_string()),
238	            None => Err("the address is not valid".to_string()),
239	        };
240	        match stream {
241	            Ok(mut s) => {
242	                let _ = s.set_read_timeout(Some(Duration::from_millis(50)));
243	                let _ = s.set_nodelay(true);
244	                send(Event::Status(Status::Connected));
245	                send(Event::Log(LogKind::Ok, "Connected to the fan.".into()));
246	                let mut buf = [0u8; 1024];
247	                loop {
248	                    match rx.recv_timeout(Duration::from_millis(100)) {
249	                        Ok(Cmd::Upload(files)) => {
250	                            if let Err(e) = send_files(&mut s, &files, &send) {
251	                                send(Event::Log(LogKind::Warn, format!("Upload failed: {e}")));
252	                            }
253	                            send(Event::Progress(None));
254	                        }
255	                        Ok(cmd) => {
256	                            let line = format!("{}\n", cmd.wire());
257	                            if let Err(e) = s.write_all(line.as_bytes()) {
258	                                send(Event::Log(LogKind::Warn, format!("Connection lost: {e}")));
259	                                break;
260	                            }
261	                        }
262	                        Err(RecvTimeoutError::Timeout) => {}
263	                        Err(RecvTimeoutError::Disconnected) => return,
264	                    }
265	                    match s.read(&mut buf) {
266	                        Ok(0) => {
267	                            send(Event::Log(LogKind::Warn, "The fan closed the connection.".into()));
268	                            break;
269	                        }
270	                        Ok(n) => {
271	                            let text = String::from_utf8_lossy(&buf[..n]).trim().to_string();
272	                            if !text.is_empty() {
273	                                send(Event::Log(LogKind::Fan, text));
274	                            }
275	                        }
276	                        Err(_) => {} // timeout: nothing to read
277	                    }
278	                }
279	            }
280	            Err(e) => {
281	                send(Event::Status(Status::Failed));
282	                send(Event::Log(LogKind::Warn, format!("No answer from the fan ({e}). Retrying in 5 seconds.")));
283	            }
284	        }
285	        // wait before retrying, but stop at once when disconnected
286	        let until = Instant::now() + Duration::from_secs(5);
287	        while Instant::now() < until {
288	            match rx.recv_timeout(Duration::from_millis(200)) {
289	                Err(RecvTimeoutError::Disconnected) => return,
290	                _ => {}
291	            }
292	        }
293	    }
294	}
295	
296	fn send_files(s: &mut TcpStream, files: &[PathBuf], send: &dyn Fn(Event) -> bool) -> std::io::Result<()> {
297	    let total: u64 = files.iter().filter_map(|f| std::fs::metadata(f).ok()).map(|m| m.len()).sum::<u64>().max(1);
298	    let mut done = 0u64;
299	    for f in files {
300	        let name = f.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
301	        let mut file = std::fs::File::open(f)?;
302	        let len = file.metadata()?.len();
303	        s.write_all(format!("UPLOAD \"{name}\" {len}\n").as_bytes())?;
304	        let mut buf = vec![0u8; 64 * 1024];
305	        loop {
306	            let n = file.read(&mut buf)?;
307	            if n == 0 {
308	                break;
309	            }
310	            s.write_all(&buf[..n])?;
311	            done += n as u64;
312	            send(Event::Progress(Some(done as f32 / total as f32)));
313	        }
314	        send(Event::Log(LogKind::Ok, format!("Uploaded {name}")));
315	    }
316	    Ok(())
317	}
