[package.metadata.bundle]
name = "HoloFan Studio"
identifier = "app.holofanstudio.desktop"
version = "13.0.0"
category = "public.app-category.utilities"
short_description = "Control and program 3D hologram fans"
osx_minimum_system_version = "11.0"
