261	                } else {
262	                    self.notify(&ctx, "Preparing videos needs ffmpeg (ffmpeg.org) installed", false);
263	                    self.dev.push_log(LogKind::Warn, "ffmpeg was not found, so videos can't be prepared. The original files are used instead.");
264	                }
265	            }
266	            let can_up = !self.media.items.is_empty() && self.dev.upload_progress.is_none();
267	            if outline_button(ui, p, "Upload to fan", can_up).clicked() {
268	                let files: Vec<PathBuf> = self.media.items.iter().map(|i| i.output().to_path_buf()).collect();
269	                self.send(&ctx, Cmd::Upload(files));
