275	                let total: u64 = self.media.items.iter().map(|i| i.size).sum();
276	                chip(ui, &format!("{} item(s) · {}", self.media.items.len(), fmt_bytes(total)), p.accent, p.accent_soft);
277	            });
278	        });
279	        if let Some(pr) = self.dev.upload_progress {
280	            ui.add_space(8.0);
281	            ui.label(RichText::new(format!("Uploading… {:.0}%", pr * 100.0)).size(12.0).color(p.muted));
282	            bar(ui, p, pr, p.accent, 6.0);
283	        }
284	        ui.add_space(12.0);
285	
286	        // playlist
287	        card_frame(p).inner_margin(Margin::same(8)).show(ui, |ui| {
288	            ui.set_min_width(ui.available_width());
289	            if self.media.items.is_empty() {
290	                ui.add_space(26.0);
291	                ui.vertical_centered(|ui| {
292	                    ui.label(RichText::new("🎞").size(34.0).color(p.faint));
293	                    ui.add_space(4.0);
294	                    ui.label(RichText::new("Your playlist is empty").font(FontId::new(15.0, bold())).color(p.text));
295	                    ui.label(RichText::new("Click “Add files” or drop videos and pictures onto this window").color(p.muted));
296	                });
297	                ui.add_space(26.0);
298	                return;
299	            }
300	            let mut action: Option<(usize, i8)> = None; // 0 select, -1 up, 1 down, 2 remove

