// The four pages of HoloFan Studio: Player, Media & SD card, Clock and Device.

use std::path::PathBuf;
use std::time::Duration;

use eframe::egui::{
    self, Align, Align2, Color32, CornerRadius, FontId, Frame, Id, Layout, Margin, Rect, RichText,
    ScrollArea, Sense, Stroke, TextEdit, Ui, pos2, vec2,
};

use crate::app::{App, Confirm, DIALS, LoopMode, status_look};
use crate::device::{Cmd, LogKind};
use crate::media::{self, Kind, fmt_bytes};
use crate::models::MODELS;
use crate::paint::{self, input_frame, round_button, setting_row, short, small_icon_button, time_field};
use crate::theme::{ACCENTS, Palette, ThemeMode, bold, mix};
use crate::widgets::*;

fn outline_button(ui: &mut Ui, p: &Palette, text: &str, enabled: bool) -> egui::Response {
    ui.add_enabled(
        enabled,
        egui::Button::new(RichText::new(text).color(p.text)).fill(p.card).stroke(Stroke::new(1.0, p.border)).corner_radius(10).min_size(vec2(0.0, 36.0)),
    )
}

impl App {
    // ------------------------------------------------------------------ player

    pub(crate) fn page_player(&mut self, ui: &mut Ui, p: &Palette) {
        let ctx = ui.ctx().clone();
        page_header(ui, p, "Player", "Control what your hologram fan shows");
        let time = ctx.input(|i| i.time) as f32;
        let total_w = ui.available_width();
        let left_w = (total_w * 0.52).floor();
        let right_w = total_w - left_w - 16.0;

        ui.horizontal_top(|ui| {
            ui.spacing_mut().item_spacing.x = 16.0;
            // ---- left: preview + transport
            ui.vertical(|ui| {
                ui.set_width(left_w);
                card(ui, p, |ui| {
                    ui.set_width(left_w - 36.0);
                    let n = self.media.items.len();
                    ui.horizontal(|ui| {
                        ui.label(title("Now showing", 16.0, p.text));
                        ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                            let mode = if self.loop_mode == LoopMode::Single { "Single loop" } else { "List loop" };
                            chip(ui, mode, p.accent, p.accent_soft);
                            if !self.powered {
                                chip(ui, "Off", p.muted, p.track);
                            }
                        });
                    });
                    ui.add_space(6.0);
                    let item_idx = if n > 0 { Some(self.media.current.min(n - 1)) } else { None };
                    if let Some(i) = item_idx {
                        self.media.items[i].load_thumb(&ctx);
                    }
                    let blades = self.model.map(|m| MODELS[m].blades()).unwrap_or(2);
                    let size = (left_w - 36.0).min(250.0);
                    ui.vertical_centered(|ui| {
                        let (rect, _) = ui.allocate_exact_size(vec2(size, size), Sense::hover());
                        let item = item_idx.map(|i| &self.media.items[i]);
                        paint::fan(ui.painter(), rect, p, item, blades, self.playing && self.powered, self.powered, time, self.brightness);
                    });
                    ui.add_space(8.0);
                    ui.vertical_centered(|ui| match item_idx {
                        Some(i) => {
                            let it = &self.media.items[i];
                            ui.label(RichText::new(short(&it.name, 44)).font(FontId::new(15.0, bold())).color(p.text));
                            ui.label(RichText::new(format!("{} of {} · {}", i + 1, n, if it.kind == Kind::Video { "Video" } else { "Picture" })).size(12.0).color(p.muted));
                        }
                        None => {
                            ui.label(RichText::new("Nothing in the playlist yet").font(FontId::new(15.0, bold())).color(p.text));
                            ui.label(RichText::new("Add videos or pictures on the Media page").size(12.0).color(p.muted));
                        }
                    });
                    ui.add_space(12.0);
                    // transport: Last one · Single loop · Play/Pause · List loop · Next one
                    let bw = 50.0;
                    let gap = 14.0;
                    let row_w = bw * 4.0 + 62.0 + gap * 4.0;
                    ui.horizontal(|ui| {
                        ui.add_space(((ui.available_width() - row_w) / 2.0).max(0.0));
                        ui.spacing_mut().item_spacing.x = gap;
                        if round_button(ui, p, "prev", "Previous", bw, false, false).clicked() {
                            self.media.step(false);
                            self.send(&ctx, Cmd::Prev);
                        }
                        if round_button(ui, p, "loop1", "Single loop", bw, self.loop_mode == LoopMode::Single, false).clicked() {
                            self.loop_mode = LoopMode::Single;
                            self.send(&ctx, Cmd::SingleLoop);
                        }
                        let (pp, cap) = if self.playing { ("pause", "Pause") } else { ("play", "Play") };
                        if round_button(ui, p, pp, cap, 62.0, false, true).clicked() {
                            self.playing = !self.playing;
                            self.send(&ctx, Cmd::PlayPause);
                        }
                        if round_button(ui, p, "loop", "List loop", bw, self.loop_mode == LoopMode::List, false).clicked() {
                            self.loop_mode = LoopMode::List;
                            self.send(&ctx, Cmd::ListLoop);
                        }
                        if round_button(ui, p, "next", "Next", bw, false, false).clicked() {
                            self.media.step(true);
                            self.send(&ctx, Cmd::Next);
                        }
                    });
                });
            });

            // ---- right: status, display, picture time
            ui.vertical(|ui| {
                ui.set_width(right_w);
                card(ui, p, |ui| {
                    ui.set_width(right_w - 36.0);
                    ui.horizontal(|ui| {
                        ui.label(title("Device status", 16.0, p.text));
                        ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                            let (dot, text) = status_look(p, &self.dev.status);
                            chip(ui, text, dot, mix(p.card, dot, 0.16));
                        });
                    });
                    ui.add_space(6.0);
                    kv(ui, p, "Fan model", &self.model_name());
                    if let Some(m) = self.model {
                        kv(ui, p, "Diameter", &format!("{:.0} cm · {} blades", MODELS[m].cm(), MODELS[m].blades()));
                    }
                    kv(ui, p, "Address", &self.dev.address.clone());
                    ui.add_space(4.0);
                    ui.horizontal(|ui| {
                        ui.label(RichText::new("Power").font(FontId::new(14.0, bold())).color(p.text));
                        ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                            let mut on = self.powered;
                            if toggle(ui, p, &mut on).changed() {
                                self.powered = on;
                                self.send(&ctx, Cmd::Power);
                            }
                            ui.label(RichText::new(if self.powered { "On" } else { "Off" }).color(p.muted));
                        });
                    });
                });
                ui.add_space(14.0);
                card(ui, p, |ui| {
                    ui.set_width(right_w - 36.0);
                    ui.label(title("Display", 16.0, p.text));
                    ui.add_space(8.0);
                    ui.horizontal(|ui| {
                        ui.label(RichText::new("Brightness").color(p.text));
                        ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                            if small_icon_button(ui, p, "+").on_hover_text("Brightness +").clicked() {
                                self.brightness = (self.brightness + 1).min(10);
                                self.send(&ctx, Cmd::BrightnessUp);
                            }
                            ui.label(RichText::new(format!("{}", self.brightness)).font(FontId::new(14.0, bold())).color(p.text));
                            if small_icon_button(ui, p, "−").on_hover_text("Brightness −").clicked() {
                                self.brightness = (self.brightness - 1).max(1);
                                self.send(&ctx, Cmd::BrightnessDown);
                            }
                        });
                    });
                    bar(ui, p, self.brightness as f32 / 10.0, p.accent, 6.0);
                    ui.add_space(12.0);
                    ui.horizontal(|ui| {
                        ui.vertical(|ui| {
                            ui.label(RichText::new("Image alignment").color(p.text));
                            ui.label(RichText::new("Turn the picture if it looks rotated").size(11.5).color(p.muted));
                        });
                        ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                            if secondary_button(ui, p, " CW ⟳ ").on_hover_text("Clockwise adjust").clicked() {
                                self.send(&ctx, Cmd::RotateCw);
                            }
                            if secondary_button(ui, p, " ⟲ CCW ").on_hover_text("Counter-clockwise adjust").clicked() {
                                self.send(&ctx, Cmd::RotateCcw);
                            }
                        });
                    });
                });
                ui.add_space(14.0);
                card(ui, p, |ui| {
                    ui.set_width(right_w - 36.0);
                    ui.label(title("Picture play time", 16.0, p.text));
                    ui.label(RichText::new("How long each picture stays on (5–30 s)").size(11.5).color(p.muted));
                    ui.add_space(6.0);
                    ui.horizontal(|ui| {
                        let mut v = self.picture_secs;
                        ui.spacing_mut().slider_width = (right_w - 36.0 - 170.0).max(80.0);
                        if ui.add(egui::Slider::new(&mut v, 5..=30).suffix(" s")).changed() {
                            self.picture_secs = v;
                        }
                        ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                            if primary_button(ui, p, " Apply ", true).clicked() {
                                let s = self.picture_secs;
                                self.send(&ctx, Cmd::PictureTime(s));
                            }
                        });
                    });
                });
            });
        });

        ui.add_space(16.0);
        self.activity_log(ui, p, 150.0);
    }

    fn activity_log(&mut self, ui: &mut Ui, p: &Palette, height: f32) {
        card(ui, p, |ui| {
            ui.set_min_width(ui.available_width());
            ui.horizontal(|ui| {
                ui.label(title("Activity", 16.0, p.text));
                ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                    if ui.add(egui::Button::new(RichText::new("Clear").size(12.0).color(p.muted)).frame(false)).clicked() {
                        self.dev.log.clear();
                    }
                });
            });
            ui.add_space(6.0);
            Frame::new()
                .fill(if p.dark { Color32::from_rgb(16, 19, 24) } else { Color32::from_rgb(248, 249, 251) })
                .corner_radius(CornerRadius::same(10))
                .inner_margin(Margin::symmetric(12, 8))
                .show(ui, |ui| {
                    ui.set_min_width(ui.available_width());
                    ScrollArea::vertical().max_height(height).auto_shrink([false, false]).stick_to_bottom(true).show(ui, |ui| {
                        for l in &self.dev.log {
                            let (col, tag) = match l.kind {
                                LogKind::Info => (p.muted, "•"),
                                LogKind::Ok => (p.success, "✔"),
                                LogKind::Warn => (p.warning, "!"),
                                LogKind::Sent => (p.accent, "→"),
                                LogKind::Fan => (p.text, "←"),
                            };
                            ui.horizontal(|ui| {
                                ui.label(RichText::new(&l.time).monospace().size(11.5).color(p.faint));
                                ui.label(RichText::new(tag).color(col));
                                ui.label(RichText::new(&l.text).size(12.5).color(if l.kind == LogKind::Info { p.muted } else { p.text }));
                            });
                        }
                    });
                });
        });
    }

