    pub(crate) fn page_media(&mut self, ui: &mut Ui, p: &Palette) {
        let ctx = ui.ctx().clone();
        page_header(ui, p, "Media & SD card", "Build the playlist, prepare videos and put them on the fan");

        ui.horizontal(|ui| {
            if primary_button(ui, p, "  + Add files  ", true).clicked() {
                self.add_files_dialog(&ctx);
            }
            let has_videos = self.media.items.iter().any(|i| i.kind == Kind::Video);
            if outline_button(ui, p, "Prepare videos", has_videos).on_hover_text("Turns videos into square clips sized for your fan (needs ffmpeg)").clicked() {
                if self.media.has_ffmpeg() {
                    let size = self.model.map(|m| MODELS[m].video_size()).unwrap_or(720);
                    let out = eframe::storage_dir("HoloFan Studio").unwrap_or_else(std::env::temp_dir).join("prepared");
                    let n = self.media.prepare_videos(size, out, &ctx);
                    self.dev.push_log(LogKind::Info, format!("Preparing {n} video(s) at {size}×{size}…"));
                } else {
                    self.notify(&ctx, "Preparing videos needs ffmpeg (ffmpeg.org) installed", false);
                    self.dev.push_log(LogKind::Warn, "ffmpeg was not found, so videos can't be prepared. The original files are used instead.");
                }
            }
            let can_up = !self.media.items.is_empty() && self.dev.upload_progress.is_none();
            if outline_button(ui, p, "Upload to fan", can_up).clicked() {
                let files: Vec<PathBuf> = self.media.items.iter().map(|i| i.output().to_path_buf()).collect();
                self.send(&ctx, Cmd::Upload(files));
            }
            ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                if !self.media.items.is_empty() && ui.add(egui::Button::new(RichText::new("Clear list").size(12.5).color(p.muted)).frame(false)).clicked() {
                    self.confirm = Some(Confirm::ClearPlaylist);
                }
                let total: u64 = self.media.items.iter().map(|i| i.size).sum();
                chip(ui, &format!("{} item(s) · {}", self.media.items.len(), fmt_bytes(total)), p.accent, p.accent_soft);
            });
        });
        if let Some(pr) = self.dev.upload_progress {
            ui.add_space(8.0);
            ui.label(RichText::new(format!("Uploading… {:.0}%", pr * 100.0)).size(12.0).color(p.muted));
            bar(ui, p, pr, p.accent, 6.0);
        }
        ui.add_space(12.0);

        // playlist
        card_frame(p).inner_margin(Margin::same(8)).show(ui, |ui| {
            ui.set_min_width(ui.available_width());
            if self.media.items.is_empty() {
                ui.add_space(26.0);
                ui.vertical_centered(|ui| {
                    ui.label(RichText::new("🎞").size(34.0).color(p.faint));
                    ui.add_space(4.0);
                    ui.label(RichText::new("Your playlist is empty").font(FontId::new(15.0, bold())).color(p.text));
                    ui.label(RichText::new("Click “Add files” or drop videos and pictures onto this window").color(p.muted));
                });
                ui.add_space(26.0);
                return;
            }
            let mut action: Option<(usize, i8)> = None; // 0 select, -1 up, 1 down, 2 remove

