399	                        painter.rect_stroke(r, 12, Stroke::new(if sel { 2.0 } else { 1.0 }, if sel || hover { p.accent } else { p.border }), egui::StrokeKind::Inside);
400	                        painter.text(pos2(r.center().x, r.top() + 22.0), Align2::CENTER_CENTER, m.code, FontId::new(15.0, bold()), p.text);
401	                        painter.text(pos2(r.center().x, r.top() + 42.0), Align2::CENTER_CENTER, format!("{} · {:.0} cm", m.size_label(), m.cm()), FontId::proportional(12.0), p.muted);
402	                        if resp.on_hover_cursor(egui::CursorIcon::PointingHand).clicked() {
403	                            self.model = Some(idx);
404	                            self.dev.push_log(LogKind::Info, format!("Fan model set to {} ({})", m.code, m.size_label()));
