481	                    .multiply_with_opacity(alpha)
482	                    .show(ui, |ui| {
483	                        ui.horizontal(|ui| {
484	                            ui.label(RichText::new(if ok { "✔" } else { "⚠" }).color(if ok { p.success } else { p.warning }));
485	                            ui.label(RichText::new(msg).color(Color32::WHITE));
486	                        });
487	                    });
488	            });
