    // ------------------------------------------------------------------ dialogs

    fn model_picker(&mut self, ctx: &egui::Context, p: &Palette) {
        if !self.picking_model {
            return;
        }
        let first = self.model.is_none();
        let mut close = false;
        let resp = egui::Modal::new(Id::unique("model-picker")).frame(modal_frame(p)).show(ctx, |ui| {
            ui.set_width(660.0);
            ui.label(title("Choose your fan model", 20.0, p.text));
            ui.label(RichText::new("The code and size are printed on the fan or its box.").color(p.muted));
            ui.add_space(14.0);
            let cols = 5;
            let gap = 10.0;
            let tw = (660.0 - gap * (cols as f32 - 1.0)) / cols as f32;
            for (row_i, row) in MODELS.chunks(cols).enumerate() {
                ui.horizontal(|ui| {
                    ui.spacing_mut().item_spacing.x = gap;
                    for (j, m) in row.iter().enumerate() {
                        let idx = row_i * cols + j;
                        let (r, resp) = ui.allocate_exact_size(vec2(tw, 62.0), Sense::click());
                        let sel = self.model == Some(idx);
                        let hover = resp.hovered();
                        let painter = ui.painter();
                        painter.rect_filled(r, 12, if sel { p.accent_soft } else if hover { p.card_hover } else { p.bg });
                        painter.rect_stroke(r, 12, Stroke::new(if sel { 2.0 } else { 1.0 }, if sel || hover { p.accent } else { p.border }), egui::StrokeKind::Inside);
                        painter.text(pos2(r.center().x, r.top() + 22.0), Align2::CENTER_CENTER, m.code, FontId::new(15.0, bold()), p.text);
                        painter.text(pos2(r.center().x, r.top() + 42.0), Align2::CENTER_CENTER, format!("{} · {:.0} cm", m.size_label(), m.cm()), FontId::proportional(12.0), p.muted);
                        if resp.on_hover_cursor(egui::CursorIcon::PointingHand).clicked() {
                            self.model = Some(idx);
                            self.dev.push_log(LogKind::Info, format!("Fan model set to {} ({})", m.code, m.size_label()));
                            if self.dev.is_connected() {
                                self.dev.send(Cmd::Model(m.code.to_string()));
                            }
                            close = true;
                        }
                    }
                });
                ui.add_space(gap - 8.0);
            }
            if !first {
                ui.add_space(8.0);
                ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                    if secondary_button(ui, p, "  Cancel  ").clicked() {
                        close = true;
                    }
                });
            }
        });
        if close || (resp.should_close() && !first) {
            self.picking_model = false;
        }
    }

    fn confirm_dialog(&mut self, ctx: &egui::Context, p: &Palette) {
        let Some(c) = self.confirm else { return };
        let (head, body, action) = match c {
            Confirm::Format => ("Format the fan's storage?", "Every video and picture stored on the fan will be erased. This can't be undone.", "  Format  "),
            Confirm::ClearCache => ("Clear the fan's cache?", "Temporary data on the fan will be removed. Your videos stay.", "  Clear cache  "),
            Confirm::ClearPlaylist => ("Clear the playlist?", "All items are removed from the list. The files on your computer stay.", "  Clear list  "),
        };
        let mut close = false;
        let resp = egui::Modal::new(Id::unique("confirm")).frame(modal_frame(p)).show(ctx, |ui| {
            ui.set_width(400.0);
            ui.label(title(head, 18.0, p.text));
            ui.add_space(6.0);
            ui.label(RichText::new(body).color(p.muted));
            ui.add_space(14.0);
            ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                if danger_button(ui, p, action).clicked() {
                    match c {
                        Confirm::Format => self.send(ctx, Cmd::FormatDisk),
                        Confirm::ClearCache => self.send(ctx, Cmd::ClearCache),
                        Confirm::ClearPlaylist => {
                            self.media.items.clear();
                            self.media.current = 0;
                        }
                    }
                    close = true;
                }
                if secondary_button(ui, p, "  Cancel  ").clicked() {
                    close = true;
                }
            });
        });
        if close || resp.should_close() {
            self.confirm = None;
        }
    }

    fn toast_ui(&mut self, ctx: &egui::Context, p: &Palette) {
        let Some((msg, ok, at)) = self.toast.clone() else { return };
        let age = (ctx.input(|i| i.time) - at) as f32;
        if age > 3.5 {
            self.toast = None;
            return;
        }
        ctx.request_repaint_after(Duration::from_millis(50));
        let alpha = (3.5 - age).clamp(0.0, 0.4) / 0.4;
        egui::Area::new(Id::unique("toast"))
            .anchor(Align2::CENTER_BOTTOM, vec2(122.0, -28.0))
            .order(egui::Order::Foreground)
            .show(ctx, |ui| {
                Frame::new()
                    .fill(if p.dark { Color32::from_rgb(38, 43, 51) } else { Color32::from_rgb(17, 24, 39) })
                    .corner_radius(CornerRadius::same(12))
                    .inner_margin(Margin::symmetric(16, 10))
                    .multiply_with_opacity(alpha)
                    .show(ui, |ui| {
                        ui.horizontal(|ui| {
                            ui.label(RichText::new(if ok { "✔" } else { "⚠" }).color(if ok { p.success } else { p.warning }));
                            ui.label(RichText::new(msg).color(Color32::WHITE));
                        });
                    });
            });
    }
}

pub fn status_look(p: &Palette, s: &Status) -> (Color32, &'static str) {
    match s {
        Status::Connected => (p.success, "Connected"),
        Status::Connecting => (p.warning, "Connecting…"),
        Status::Failed => (p.danger, "Not connected"),
        Status::Disconnected => (p.faint, "Disconnected"),
    }
}

impl eframe::App for App {
    fn ui(&mut self, ui: &mut Ui, _frame: &mut eframe::Frame) {
        let ctx = ui.ctx().clone();
        self.handle_screenshot(&ctx);

        if self.applied != Some((self.theme_mode, self.accent_idx)) {
            theme::apply(&ctx, self.theme_mode, self.accent());
            self.applied = Some((self.theme_mode, self.accent_idx));
        }

        self.dev.poll();
        for (ok, text) in self.media.poll() {
            self.dev.push_log(if ok { LogKind::Ok } else { LogKind::Warn }, text.clone());
            self.notify(&ctx, text, ok);
        }
        // files dropped onto the window go into the playlist
        let dropped: Vec<PathBuf> = ctx.input(|i| i.raw.dropped_files.iter().map(|f| f.path().to_path_buf()).filter(|p| !p.as_os_str().is_empty()).collect());
        if !dropped.is_empty() {
            self.add_paths(&ctx, dropped);
        }

        let p = theme::palette(ui.visuals().dark_mode, self.accent());

        egui::Panel::left("sidebar")
            .resizable(false)
            .exact_size(244.0)
            .frame(Frame::new().fill(p.sidebar).inner_margin(Margin { left: 16, right: 16, top: 22, bottom: 16 }))
            .show(ui, |ui| {
                let r = ui.max_rect();
                ui.painter().vline(r.right() + 16.0, ui.clip_rect().y_range(), Stroke::new(1.0, p.border));
                self.sidebar(ui, &p);
            });

        egui::CentralPanel::default()
            .frame(Frame::new().fill(p.bg).inner_margin(Margin { left: 32, right: 32, top: 28, bottom: 20 }))
            .show(ui, |ui| {
                ScrollArea::vertical().auto_shrink([false, false]).show(ui, |ui| {
                    ui.set_width(ui.available_width() - 8.0);
                    match self.page {
                        Page::Player => self.page_player(ui, &p),
                        Page::Media => self.page_media(ui, &p),
                        Page::Clock => self.page_clock(ui, &p),
                        Page::Device => self.page_device(ui, &p),
                    }
                    ui.add_space(12.0);
                });
            });

        self.model_picker(&ctx, &p);
        self.confirm_dialog(&ctx, &p);
        self.toast_ui(&ctx, &p);

        // the fan preview, the logo and the connection pulse are animated
        ctx.request_repaint_after(Duration::from_millis(if self.page == Page::Player { 33 } else { 100 }));
    }

    fn save(&mut self, storage: &mut dyn eframe::Storage) {
        if self.shot_path.is_some() {
            return;
        }
        let mut put = |k: &str, v: String| storage.set_string(k, v);
        put("page", self.page.key().into());
        put("theme", self.theme_mode.key().into());
        put("accent", self.accent_idx.to_string());
        if let Some(m) = self.model {
            put("model", MODELS[m].code.into());
        }
        put("address", self.dev.address.clone());
        put("brightness", self.brightness.to_string());
        put("picture_secs", self.picture_secs.to_string());
        put("clock_on", if self.clock_on { "1" } else { "0" }.into());
        put("needle", if self.needle_white { "white" } else { "black" }.into());
        put("dial", self.dial.to_string());
        put("boot_h", self.boot_h.to_string());
        put("boot_m", self.boot_m.to_string());
        put("boot_s", self.boot_s.to_string());
        put("ssid", self.wifi_ssid.clone());
        if let Some(t) = &self.sd_target {
            put("sd_target", t.display().to_string());
        }
        let list: Vec<String> = self.media.items.iter().map(|i| i.path.display().to_string()).collect();
        put("playlist", list.join("\n"));
    }
}

