                            let sel = i == self.dial;
                            let painter = ui.painter();
                            painter.rect_filled(r, 12, if sel { p.accent_soft } else if resp.hovered() { p.card_hover } else { p.card });
                            painter.rect_stroke(r, 12, Stroke::new(if sel { 2.0 } else { 1.0 }, if sel { p.accent } else { p.border }), egui::StrokeKind::Inside);
                            let face = Rect::from_center_size(pos2(r.center().x, r.top() + tw / 2.0 + 2.0), vec2(tw - 24.0, tw - 24.0));
                            paint::clock(painter, face, i, self.needle_white, &now, false);
                            painter.text(
                                pos2(r.center().x, r.bottom() - 14.0),
                                Align2::CENTER_CENTER,
                                *d,
                                FontId::new(12.0, if sel { bold() } else { egui::FontFamily::Proportional }),
                                if sel { p.text } else { p.muted },
