    // ------------------------------------------------------------------ device

    pub(crate) fn page_device(&mut self, ui: &mut Ui, p: &Palette) {
        let ctx = ui.ctx().clone();
        page_header(ui, p, "Device", "Fan model, connection, Wi-Fi and maintenance");
        let total_w = ui.available_width();
        let col_w = ((total_w - 16.0) / 2.0).floor();
        let t = ctx.input(|i| i.time) as f32;
        ui.horizontal_top(|ui| {
            ui.spacing_mut().item_spacing.x = 16.0;
            ui.vertical(|ui| {
                ui.set_width(col_w);
                card(ui, p, |ui| {
                    ui.set_width(col_w - 36.0);
                    ui.label(title("Fan model", 16.0, p.text));
                    ui.add_space(8.0);
                    ui.horizontal(|ui| {
                        let (r, _) = ui.allocate_exact_size(vec2(56.0, 56.0), Sense::hover());
                        paint::fan_icon(ui.painter(), r, p, self.model.map(|m| MODELS[m].blades()).unwrap_or(2), t);
                        ui.vertical(|ui| {
                            ui.label(RichText::new(self.model_name()).font(FontId::new(18.0, bold())).color(p.text));
                            if let Some(m) = self.model {
                                let vs = MODELS[m].video_size();
                                ui.label(RichText::new(format!("{:.1} cm · videos prepared at {vs}×{vs}", MODELS[m].cm())).size(12.0).color(p.muted));
                            }
                        });
                    });
                    ui.add_space(10.0);
                    if secondary_button(ui, p, "  Change model  ").clicked() {
                        self.picking_model = true;
                    }
                });
                ui.add_space(14.0);
                card(ui, p, |ui| {
                    ui.set_width(col_w - 36.0);
                    ui.horizontal(|ui| {
                        ui.label(title("Connection", 16.0, p.text));
                        ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                            let (dot, text) = status_look(p, &self.dev.status);
                            chip(ui, text, dot, mix(p.card, dot, 0.16));
                        });
                    });
                    ui.label(RichText::new("Join the fan's Wi-Fi first, then connect to its address.").size(12.0).color(p.muted));
                    ui.add_space(10.0);
                    ui.label(RichText::new("Fan address (IP:port)").size(12.5).color(p.text));
                    input_frame(p).show(ui, |ui| {
                        ui.add(TextEdit::singleline(&mut self.addr_edit).frame(Frame::NONE).desired_width(f32::INFINITY).hint_text("192.168.4.1:5000"));
                    });
                    ui.add_space(10.0);
                    ui.horizontal(|ui| {
                        if primary_button(ui, p, if self.dev.is_active() { "  Reconnect  " } else { "  Connect  " }, true).clicked() {
                            self.dev.address = self.addr_edit.trim().to_string();
                            self.dev.connect(&ctx);
                        }
                        if self.dev.is_active() && secondary_button(ui, p, "  Disconnect  ").clicked() {
                            self.dev.disconnect();
                        }
                    });
                });
                ui.add_space(14.0);
                card(ui, p, |ui| {
                    ui.set_width(col_w - 36.0);
                    ui.label(title("Appearance", 16.0, p.text));
                    ui.add_space(8.0);
                    setting_row(ui, p, "Theme", "System, light or dark", |ui| {
                        let modes = [ThemeMode::System, ThemeMode::Light, ThemeMode::Dark];
                        let idx = modes.iter().position(|m| *m == self.theme_mode).unwrap_or(0);
                        let labels: Vec<&str> = modes.iter().map(|m| m.label()).collect();
                        if let Some(i) = segmented(ui, p, &labels, idx) {
                            self.theme_mode = modes[i];
                        }
                    });
                    setting_row(ui, p, "Accent colour", ACCENTS[self.accent_idx].0, |ui| {
                        for i in (0..ACCENTS.len()).rev() {
                            let (rect, resp) = ui.allocate_exact_size(vec2(24.0, 24.0), Sense::click());
                            if i == self.accent_idx {
                                ui.painter().circle_stroke(rect.center(), 11.0, Stroke::new(2.0, ACCENTS[i].1));
                            }
                            ui.painter().circle_filled(rect.center(), 8.0, ACCENTS[i].1);
                            if resp.on_hover_text(ACCENTS[i].0).clicked() {
                                self.accent_idx = i;
                            }
                        }
                    });
                });
            });
            ui.vertical(|ui| {
                ui.set_width(col_w);
                card(ui, p, |ui| {
                    ui.set_width(col_w - 36.0);
                    ui.label(title("Wi-Fi setup", 16.0, p.text));
                    ui.label(RichText::new("Send your network name and password to the fan.").size(12.0).color(p.muted));
                    ui.add_space(10.0);
                    ui.label(RichText::new("Network name (SSID)").size(12.5).color(p.text));
                    input_frame(p).show(ui, |ui| {
                        ui.add(TextEdit::singleline(&mut self.wifi_ssid).frame(Frame::NONE).desired_width(f32::INFINITY).hint_text("My Wi-Fi"));
                    });
                    ui.add_space(8.0);
                    ui.label(RichText::new("Password").size(12.5).color(p.text));
                    input_frame(p).show(ui, |ui| {
                        ui.horizontal(|ui| {
                            let w = ui.available_width() - 48.0;
                            ui.add(TextEdit::singleline(&mut self.wifi_pass).password(!self.show_pass).frame(Frame::NONE).desired_width(w).hint_text("At least 8 characters"));
                            if ui.add(egui::Button::new(RichText::new(if self.show_pass { "Hide" } else { "Show" }).size(12.0).color(p.muted)).frame(false)).clicked() {
                                self.show_pass = !self.show_pass;
                            }
                        });
                    });
                    ui.add_space(10.0);
                    let ok = !self.wifi_ssid.trim().is_empty();
                    if primary_button(ui, p, "  Send Wi-Fi settings  ", ok).clicked() {
                        let cmd = Cmd::Wifi { ssid: self.wifi_ssid.trim().to_string(), password: self.wifi_pass.clone() };
                        self.send(&ctx, cmd);
                    }
                });
                ui.add_space(14.0);
                card(ui, p, |ui| {
                    ui.set_width(col_w - 36.0);
                    ui.label(title("Maintenance", 16.0, p.text));
                    ui.add_space(8.0);
                    setting_row(ui, p, "Clear cache", "Remove temporary data on the fan", |ui| {
                        if secondary_button(ui, p, "  Clear cache  ").clicked() {
                            self.confirm = Some(Confirm::ClearCache);
                        }
                    });
                    divider(ui, p);
                    ui.add_space(8.0);
                    setting_row(ui, p, "Format fan storage", "Erase every video on the fan", |ui| {
                        if danger_button(ui, p, "  Format  ").clicked() {
                            self.confirm = Some(Confirm::Format);
                        }
                    });
                });
                ui.add_space(14.0);
                card(ui, p, |ui| {
                    ui.set_width(col_w - 36.0);
                    ui.label(title("About", 16.0, p.text));
                    ui.add_space(4.0);
                    ui.label(RichText::new("HoloFan Studio 13.0 for Windows and macOS.").color(p.muted));
                    ui.label(RichText::new("The fan's network commands are a best guess. If the fan doesn't react, use “Save to SD card” instead.").size(12.0).color(p.faint));
                });
            });
        });
    }
