375	    fn model_picker(&mut self, ctx: &egui::Context, p: &Palette) {
376	        if !self.picking_model {
377	            return;
378	        }
379	        let first = self.model.is_none();
380	        let mut close = false;
381	        let resp = egui::Modal::new(Id::unique("model-picker")).frame(modal_frame(p)).show(ctx, |ui| {
382	            ui.set_width(660.0);
383	            ui.label(title("Choose your fan model", 20.0, p.text));
384	            ui.label(RichText::new("The code and size are printed on the fan or its box.").color(p.muted));
385	            ui.add_space(14.0);
386	            let cols = 5;
387	            let gap = 10.0;
388	            let tw = (660.0 - gap * (cols as f32 - 1.0)) / cols as f32;
389	            for (row_i, row) in MODELS.chunks(cols).enumerate() {
390	                ui.horizontal(|ui| {
391	                    ui.spacing_mut().item_spacing.x = gap;
392	                    for (j, m) in row.iter().enumerate() {
393	                        let idx = row_i * cols + j;
394	                        let (r, resp) = ui.allocate_exact_size(vec2(tw, 62.0), Sense::click());
395	                        let sel = self.model == Some(idx);
396	                        let hover = resp.hovered();
397	                        let painter = ui.painter();
398	                        painter.rect_filled(r, 12, if sel { p.accent_soft } else if hover { p.card_hover } else { p.bg });
399	                        painter.rect_stroke(r, 12, Stroke::new(if sel { 2.0 } else { 1.0 }, if sel || hover { p.accent } else { p.border }), egui::StrokeKind::Inside);
400	                        painter.text(pos2(r.center().x, r.top() + 22.0), Align2::CENTER_CENTER, m.code, FontId::new(15.0, bold()), p.text);
401	                        painter.text(pos2(r.center().x, r.top() + 42.0), Align2::CENTER_CENTER, format!("{} · {:.0} cm", m.size_label(), m.cm()), FontId::proportional(12.0), p.muted);
402	                        if resp.on_hover_cursor(egui::CursorIcon::PointingHand).clicked() {
403	                            self.model = Some(idx);
404	                            self.dev.push_log(LogKind::Info, format!("Fan model set to {} ({})", m.code, m.size_label()));
405	                            if self.dev.is_connected() {
406	                                self.dev.send(Cmd::Model(m.code.to_string()));
407	                            }
408	                            close = true;
409	                        }
410	                    }
411	                });
412	                ui.add_space(gap - 8.0);
413	            }
414	            if !first {
415	                ui.add_space(8.0);
416	                ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
417	                    if secondary_button(ui, p, "  Cancel  ").clicked() {
418	                        close = true;
419	                    }
420	                });
421	            }
422	        });
423	        if close || (resp.should_close() && !first) {
424	            self.picking_model = false;
425	        }
426	    }
