428	    fn confirm_dialog(&mut self, ctx: &egui::Context, p: &Palette) {
429	        let Some(c) = self.confirm else { return };
430	        let (head, body, action) = match c {
431	            Confirm::Format => ("Format the fan's storage?", "Every video and picture stored on the fan will be erased. This can't be undone.", "  Format  "),
432	            Confirm::ClearCache => ("Clear the fan's cache?", "Temporary data on the fan will be removed. Your videos stay.", "  Clear cache  "),
433	            Confirm::ClearPlaylist => ("Clear the playlist?", "All items are removed from the list. The files on your computer stay.", "  Clear list  "),
434	        };
435	        let mut close = false;
436	        let resp = egui::Modal::new(Id::unique("confirm")).frame(modal_frame(p)).show(ctx, |ui| {
437	            ui.set_width(400.0);
438	            ui.label(title(head, 18.0, p.text));
439	            ui.add_space(6.0);
440	            ui.label(RichText::new(body).color(p.muted));
441	            ui.add_space(14.0);
442	            ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
443	                if danger_button(ui, p, action).clicked() {
444	                    match c {
