        assert_eq!(parse_address("192.168.4.120320"), ("192.168.4.1".into(), 20320));
        assert_eq!(parse_address("192.168.4.1"), ("192.168.4.1".into(), 20320));
        assert_eq!(parse_address("192.168.4.1:5000"), ("192.168.4.1".into(), 5000));
        assert_eq!(parse_address("10.0.0.7 20320"), ("10.0.0.7".into(), 20320));
