/// The original keeps one 5-byte buffer for every 'b' (clock) command: option commands only
/// change bytes 1 and 4, so bytes 2 and 3 keep what the last time command left there.
#[derive(Default)]
pub struct ClockBuffer([u8; 5]);

impl ClockBuffer {
