    pub current: u8,
    pub device_type: u8,
    pub audio_version: bool,
    pub sleeping: bool,
    /// 0 high, 1 medium, anything else low.
    pub brightness: u8,
    pub list_loop: bool,
    pub paused: bool,
    pub clock_version: bool,
}

