    /// Clock commands only work on fans that report a clock, as in the original.
    fn send_clock(&mut self, ctx: &egui::Context, cmd: Cmd) {
        if let Some(st) = &self.dev.fan {
            if !st.clock_version {
                self.notify(ctx, "This fan doesn't support the clock display", false);
                self.dev.push_log(LogKind::Warn, "The connected fan reports no clock, so the clock settings weren't sent.");
                return;
            }
        }
        self.send(ctx, cmd);
    }

    /// The files stored on the fan, as it reports them, with Play and Delete.
    fn fan_files(&mut self, ui: &mut Ui, p: &Palette) {
        let ctx = ui.ctx().clone();
        let Some(st) = self.dev.fan.clone() else {
            card(ui, p, |ui| {
                ui.set_min_width(ui.available_width());
                ui.label(title("Files on the fan", 16.0, p.text));
                ui.label(RichText::new("Connect to the fan to see the files it has stored.").size(12.0).color(p.muted));
            });
            return;
        };
        card(ui, p, |ui| {
            ui.set_min_width(ui.available_width());
            ui.horizontal(|ui| {
                ui.label(title("Files on the fan", 16.0, p.text));
                ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                    chip(ui, &format!("{} file(s)", st.files.len()), p.accent, p.accent_soft);
                });
            });
            ui.add_space(6.0);
            if st.files.is_empty() {
                ui.label(RichText::new("The fan has no files yet. Upload .BIN files or put them on its SD card.").size(12.0).color(p.muted));
                return;
            }
            let mut action: Option<Cmd> = None;
            for (i, name) in st.files.iter().enumerate() {
                let playing = i == st.current as usize;
                Frame::new()
                    .fill(if playing { p.accent_soft } else { Color32::TRANSPARENT })
                    .corner_radius(CornerRadius::same(8))
                    .inner_margin(Margin::symmetric(10, 4))
                    .show(ui, |ui| {
                        ui.set_min_width(ui.available_width());
                        ui.horizontal(|ui| {
                            ui.label(RichText::new(format!("{:02}", i + 1)).monospace().size(12.0).color(p.muted));
                            ui.label(RichText::new(short(name, 48)).size(13.0).color(p.text));
                            if playing {
                                chip(ui, "Playing", p.accent, p.card);
                            }
                            ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                                if ui.add(egui::Button::new(RichText::new("Delete").size(12.0).color(p.danger)).frame(false)).clicked() {
                                    action = Some(Cmd::DeleteFile(i));
                                }
                                if ui.add(egui::Button::new(RichText::new("Play").size(12.0).color(p.accent)).frame(false)).clicked() {
                                    action = Some(Cmd::PlayFile(i));
                                }
                            });
                        });
                    });
            }
            if let Some(cmd) = action {
                self.send(&ctx, cmd);
            }
        });
    }
