1	// The playlist: videos and pictures for the fan, preparing videos ("decode") and saving
2	// everything to an SD card. Long work runs on background threads.
3	
4	use std::path::{Path, PathBuf};
5	use std::process::Command;
6	use std::sync::mpsc::{Receiver, Sender, channel};
7	use std::thread;
8	
9	use eframe::egui;
10	
11	pub const VIDEO_EXT: [&str; 9] = ["mp4", "mov", "avi", "mkv", "wmv", "m4v", "webm", "flv", "bin"];
12	pub const IMAGE_EXT: [&str; 6] = ["png", "jpg", "jpeg", "gif", "bmp", "webp"];
13	
14	#[derive(Clone, Copy, PartialEq)]
15	pub enum Kind {
16	    Video,
17	    Picture,
18	}
19	
20	pub struct Item {
21	    pub path: PathBuf,
22	    pub name: String,
23	    pub kind: Kind,
24	    pub size: u64,
25	    pub prepared: Option<PathBuf>,
26	    pub preparing: bool,
27	    pub thumb: Option<egui::TextureHandle>,
28	    pub thumb_tried: bool,
29	}
30	
31	impl Item {
32	    pub fn from_path(path: PathBuf) -> Option<Self> {
33	        let ext = path.extension()?.to_string_lossy().to_lowercase();
34	        let kind = if VIDEO_EXT.contains(&ext.as_str()) {
35	            Kind::Video
36	        } else if IMAGE_EXT.contains(&ext.as_str()) {
37	            Kind::Picture
38	        } else {
39	            return None;
40	        };
41	        let size = std::fs::metadata(&path).ok()?.len();
42	        Some(Self {
43	            name: path.file_name()?.to_string_lossy().to_string(),
44	            path,
45	            kind,
46	            size,
47	            prepared: None,
48	            preparing: false,
49	            thumb: None,
50	            thumb_tried: false,
51	        })
52	    }
53	
54	    /// The file that goes to the fan: the prepared video when there is one.
55	    pub fn output(&self) -> &Path {
56	        self.prepared.as_deref().unwrap_or(&self.path)
57	    }
58	
59	    pub fn load_thumb(&mut self, ctx: &egui::Context) {
60	        if self.thumb_tried || self.kind != Kind::Picture {
61	            return;
62	        }
63	        self.thumb_tried = true;
64	        if let Ok(img) = image::open(&self.path) {
65	            let t = img.thumbnail(512, 512).to_rgba8();
66	            let (w, h) = t.dimensions();
67	            let ci = egui::ColorImage::from_rgba_unmultiplied([w as usize, h as usize], t.as_raw());
68	            self.thumb = Some(ctx.load_texture(self.path.to_string_lossy(), ci, egui::TextureOptions::LINEAR));
69	        }
70	    }
71	}
72	
73	pub enum Msg {
74	    Prepared { path: PathBuf, out: Result<PathBuf, String> },
75	    ExportProgress(f32),
76	    ExportDone(Result<(usize, PathBuf), String>),
77	}
78	
79	pub struct Media {
80	    pub items: Vec<Item>,
81	    pub current: usize,
82	    pub exporting: Option<f32>,
83	    pub ffmpeg: Option<bool>,
84	    tx: Sender<Msg>,
85	    rx: Receiver<Msg>,
86	}
87	
88	impl Media {
89	    pub fn new() -> Self {
90	        let (tx, rx) = channel();
91	        Self { items: Vec::new(), current: 0, exporting: None, ffmpeg: None, tx, rx }
92	    }
93	
94	    /// Adds supported files; returns (added, skipped).
95	    pub fn add(&mut self, paths: impl IntoIterator<Item = PathBuf>) -> (usize, usize) {
96	        let (mut a, mut s) = (0, 0);
97	        for p in paths {
98	            if self.items.iter().any(|i| i.path == p) {
99	                s += 1;
100	                continue;
101	            }
102	            match Item::from_path(p) {
103	                Some(it) => {
104	                    self.items.push(it);
105	                    a += 1;
106	                }
107	                None => s += 1,
108	            }
109	        }
110	        (a, s)
111	    }
112	
113	    pub fn remove(&mut self, i: usize) {
114	        if i < self.items.len() {
115	            self.items.remove(i);
116	            if self.current >= self.items.len() {
117	                self.current = self.items.len().saturating_sub(1);
118	            }
119	        }
120	    }
121	
122	    pub fn move_item(&mut self, i: usize, up: bool) {
123	        let j = if up { i.checked_sub(1) } else { Some(i + 1) };
124	        if let Some(j) = j {
125	            if j < self.items.len() {
126	                self.items.swap(i, j);
127	                if self.current == i {
128	                    self.current = j;
129	                } else if self.current == j {
130	                    self.current = i;
131	                }
132	            }
133	        }
134	    }
135	
136	    pub fn step(&mut self, forward: bool) {
137	        let n = self.items.len();
138	        if n == 0 {
139	            return;
140	        }
141	        self.current = if forward { (self.current + 1) % n } else { (self.current + n - 1) % n };
142	    }
143	
144	    pub fn has_ffmpeg(&mut self) -> bool {
145	        *self.ffmpeg.get_or_insert_with(|| {
146	            let mut c = Command::new("ffmpeg");
147	            c.arg("-version");
148	            no_window(&mut c);
149	            c.output().map(|o| o.status.success()).unwrap_or(false)
150	        })
151	    }
152	
153	    /// "Decode video": turn each video into a square, centred MP4 sized for the fan.
154	    /// Needs ffmpeg; returns how many jobs were started.
155	    pub fn prepare_videos(&mut self, size: u32, out_dir: PathBuf, ctx: &egui::Context) -> usize {
156	        let _ = std::fs::create_dir_all(&out_dir);
157	        let mut n = 0;
158	        for it in self.items.iter_mut().filter(|i| i.kind == Kind::Video && !i.preparing) {
159	            it.preparing = true;
160	            n += 1;
161	            let src = it.path.clone();
162	            let stem = src.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| "video".into());
163	            let out = out_dir.join(format!("{stem}_{size}.mp4"));
164	            let tx = self.tx.clone();
165	            let ctx = ctx.clone();
166	            thread::spawn(move || {
167	                let filter = format!(
168	                    "scale={size}:{size}:force_original_aspect_ratio=decrease,pad={size}:{size}:(ow-iw)/2:(oh-ih)/2:black,fps=30"
169	                );
170	                let mut c = Command::new("ffmpeg");
171	                c.args(["-y", "-loglevel", "error", "-i"])
172	                    .arg(&src)
173	                    .args(["-vf", &filter, "-c:v", "libx264", "-pix_fmt", "yuv420p", "-an", "-movflags", "+faststart"])
174	                    .arg(&out);
175	                no_window(&mut c);
176	                let res = match c.output() {
177	                    Ok(o) if o.status.success() => Ok(out),
178	                    Ok(o) => Err(String::from_utf8_lossy(&o.stderr).lines().last().unwrap_or("ffmpeg failed").to_string()),
179	                    Err(e) => Err(e.to_string()),
180	                };
181	                let _ = tx.send(Msg::Prepared { path: src, out: res });
182	                ctx.request_repaint();
183	            });
184	        }
185	        n
186	    }
187	
188	    /// Copy the playlist, in order, to a folder on the SD card, plus a playlist.txt.
189	    pub fn export(&mut self, dest: PathBuf, settings_txt: String, ctx: &egui::Context) {
190	        if self.exporting.is_some() {
191	            return;
192	        }
193	        self.exporting = Some(0.0);
194	        let files: Vec<PathBuf> = self.items.iter().map(|i| i.output().to_path_buf()).collect();
195	        let tx = self.tx.clone();
196	        let ctx = ctx.clone();
197	        thread::spawn(move || {
198	            let res = (|| -> Result<(usize, PathBuf), String> {
199	                std::fs::create_dir_all(&dest).map_err(|e| format!("Can't write to {}: {e}", dest.display()))?;
200	                let total: u64 = files.iter().filter_map(|f| std::fs::metadata(f).ok()).map(|m| m.len()).sum::<u64>().max(1);
201	                let mut done = 0u64;
202	                let mut list = String::new();
203	                for (i, f) in files.iter().enumerate() {
204	                    let name = format!("{:03}_{}", i + 1, f.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default());
205	                    let len = std::fs::copy(f, dest.join(&name)).map_err(|e| format!("Copying {name} failed: {e}"))?;
206	                    done += len;
207	                    list.push_str(&name);
208	                    list.push('\n');
209	                    let _ = tx.send(Msg::ExportProgress(done as f32 / total as f32));
210	                    ctx.request_repaint();
211	                }
212	                std::fs::write(dest.join("playlist.txt"), list).map_err(|e| e.to_string())?;
213	                std::fs::write(dest.join("settings.txt"), settings_txt).map_err(|e| e.to_string())?;
214	                Ok((files.len(), dest))
215	            })();
216	            let _ = tx.send(Msg::ExportDone(res));
217	            ctx.request_repaint();
218	        });
219	    }
220	
221	    /// Apply finished work; returns messages for the activity log (ok, text).
222	    pub fn poll(&mut self) -> Vec<(bool, String)> {
223	        let mut out = Vec::new();
224	        while let Ok(m) = self.rx.try_recv() {
225	            match m {
226	                Msg::Prepared { path, out: res } => {
227	                    if let Some(it) = self.items.iter_mut().find(|i| i.path == path) {
228	                        it.preparing = false;
229	                        match res {
230	                            Ok(p) => {
231	                                out.push((true, format!("Prepared {}", it.name)));
232	                                it.prepared = Some(p);
233	                            }
234	                            Err(e) => out.push((false, format!("Could not prepare {}: {e}", it.name))),
235	                        }
236	                    }
237	                }
238	                Msg::ExportProgress(p) => self.exporting = Some(p),
239	                Msg::ExportDone(r) => {
240	                    self.exporting = None;
241	                    match r {
242	                        Ok((n, d)) => out.push((true, format!("Saved {n} file(s) to {}", d.display()))),
243	                        Err(e) => out.push((false, e)),
244	                    }
245	                }
246	            }
247	        }
248	        out
249	    }
250	}
251	
252	fn no_window(_c: &mut Command) {
253	    #[cfg(target_os = "windows")]
254	    {
255	        use std::os::windows::process::CommandExt;
256	        _c.creation_flags(0x0800_0000);
257	    }
258	}
259	
260	/// Removable drives (SD cards, USB sticks) currently attached.
261	pub fn removable_drives() -> Vec<(String, PathBuf, u64)> {
262	    let Ok(disks) = sysinfo::Disks::new_with_refreshed_list() else { return Vec::new() };
263	    disks
264	        .iter()
265	        .filter(|d| d.is_removable() && d.total_space() > 0)
