// The playlist: videos and pictures for the fan, preparing videos ("decode") and saving
// everything to an SD card. Long work runs on background threads.

use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::mpsc::{Receiver, Sender, channel};
use std::thread;

use eframe::egui;

pub const VIDEO_EXT: [&str; 9] = ["mp4", "mov", "avi", "mkv", "wmv", "m4v", "webm", "flv", "bin"];
pub const IMAGE_EXT: [&str; 6] = ["png", "jpg", "jpeg", "gif", "bmp", "webp"];

#[derive(Clone, Copy, PartialEq)]
pub enum Kind {
    Video,
    Picture,
}

pub struct Item {
    pub path: PathBuf,
    pub name: String,
    pub kind: Kind,
    pub size: u64,
    pub prepared: Option<PathBuf>,
    pub preparing: bool,
    pub thumb: Option<egui::TextureHandle>,
    pub thumb_tried: bool,
}

impl Item {
    pub fn from_path(path: PathBuf) -> Option<Self> {
        let ext = path.extension()?.to_string_lossy().to_lowercase();
        let kind = if VIDEO_EXT.contains(&ext.as_str()) {
            Kind::Video
        } else if IMAGE_EXT.contains(&ext.as_str()) {
            Kind::Picture
        } else {
            return None;
        };
        let size = std::fs::metadata(&path).ok()?.len();
        Some(Self {
            name: path.file_name()?.to_string_lossy().to_string(),
            path,
            kind,
            size,
            prepared: None,
            preparing: false,
            thumb: None,
            thumb_tried: false,
        })
    }

    /// The file that goes to the fan: the prepared video when there is one.
    pub fn output(&self) -> &Path {
        self.prepared.as_deref().unwrap_or(&self.path)
    }

    pub fn load_thumb(&mut self, ctx: &egui::Context) {
        if self.thumb_tried || self.kind != Kind::Picture {
            return;
        }
        self.thumb_tried = true;
        if let Ok(img) = image::open(&self.path) {
            let t = img.thumbnail(512, 512).to_rgba8();
            let (w, h) = t.dimensions();
            let ci = egui::ColorImage::from_rgba_unmultiplied([w as usize, h as usize], t.as_raw());
            self.thumb = Some(ctx.load_texture(self.path.to_string_lossy(), ci, egui::TextureOptions::LINEAR));
        }
    }
}

pub enum Msg {
    Prepared { path: PathBuf, out: Result<PathBuf, String> },
    ExportProgress(f32),
    ExportDone(Result<(usize, PathBuf), String>),
}

pub struct Media {
    pub items: Vec<Item>,
    pub current: usize,
    pub exporting: Option<f32>,
    pub ffmpeg: Option<bool>,
    tx: Sender<Msg>,
    rx: Receiver<Msg>,
}

impl Media {
    pub fn new() -> Self {
        let (tx, rx) = channel();
        Self { items: Vec::new(), current: 0, exporting: None, ffmpeg: None, tx, rx }
    }

    /// Adds supported files; returns (added, skipped).
    pub fn add(&mut self, paths: impl IntoIterator<Item = PathBuf>) -> (usize, usize) {
        let (mut a, mut s) = (0, 0);
        for p in paths {
            if self.items.iter().any(|i| i.path == p) {
                s += 1;
                continue;
            }
            match Item::from_path(p) {
                Some(it) => {
                    self.items.push(it);
                    a += 1;
                }
                None => s += 1,
            }
        }
        (a, s)
    }

    pub fn remove(&mut self, i: usize) {
        if i < self.items.len() {
            self.items.remove(i);
            if self.current >= self.items.len() {
                self.current = self.items.len().saturating_sub(1);
            }
        }
    }

    pub fn move_item(&mut self, i: usize, up: bool) {
        let j = if up { i.checked_sub(1) } else { Some(i + 1) };
        if let Some(j) = j {
            if j < self.items.len() {
                self.items.swap(i, j);
                if self.current == i {
                    self.current = j;
                } else if self.current == j {
                    self.current = i;
                }
            }
        }
    }

    pub fn step(&mut self, forward: bool) {
        let n = self.items.len();
        if n == 0 {
            return;
        }
        self.current = if forward { (self.current + 1) % n } else { (self.current + n - 1) % n };
    }

    pub fn has_ffmpeg(&mut self) -> bool {
        *self.ffmpeg.get_or_insert_with(|| {
            let mut c = Command::new("ffmpeg");
            c.arg("-version");
            no_window(&mut c);
            c.output().map(|o| o.status.success()).unwrap_or(false)
        })
    }

    /// "Decode video": turn each video into a square, centred MP4 sized for the fan.
    /// Needs ffmpeg; returns how many jobs were started.
    pub fn prepare_videos(&mut self, size: u32, out_dir: PathBuf, ctx: &egui::Context) -> usize {
        let _ = std::fs::create_dir_all(&out_dir);
        let mut n = 0;
        for it in self.items.iter_mut().filter(|i| i.kind == Kind::Video && !i.preparing) {
            it.preparing = true;
            n += 1;
            let src = it.path.clone();
            let stem = src.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| "video".into());
            let out = out_dir.join(format!("{stem}_{size}.mp4"));
            let tx = self.tx.clone();
            let ctx = ctx.clone();
            thread::spawn(move || {
                let filter = format!(
                    "scale={size}:{size}:force_original_aspect_ratio=decrease,pad={size}:{size}:(ow-iw)/2:(oh-ih)/2:black,fps=30"
                );
                let mut c = Command::new("ffmpeg");
                c.args(["-y", "-loglevel", "error", "-i"])
                    .arg(&src)
                    .args(["-vf", &filter, "-c:v", "libx264", "-pix_fmt", "yuv420p", "-an", "-movflags", "+faststart"])
                    .arg(&out);
                no_window(&mut c);
                let res = match c.output() {
                    Ok(o) if o.status.success() => Ok(out),
                    Ok(o) => Err(String::from_utf8_lossy(&o.stderr).lines().last().unwrap_or("ffmpeg failed").to_string()),
                    Err(e) => Err(e.to_string()),
                };
                let _ = tx.send(Msg::Prepared { path: src, out: res });
                ctx.request_repaint();
            });
        }
        n
    }

    /// Copy the playlist, in order, to a folder on the SD card, plus a playlist.txt.
    pub fn export(&mut self, dest: PathBuf, settings_txt: String, ctx: &egui::Context) {
        if self.exporting.is_some() {
            return;
        }
        self.exporting = Some(0.0);
        let files: Vec<PathBuf> = self.items.iter().map(|i| i.output().to_path_buf()).collect();
        let tx = self.tx.clone();
        let ctx = ctx.clone();
        thread::spawn(move || {
            let res = (|| -> Result<(usize, PathBuf), String> {
                std::fs::create_dir_all(&dest).map_err(|e| format!("Can't write to {}: {e}", dest.display()))?;
                let total: u64 = files.iter().filter_map(|f| std::fs::metadata(f).ok()).map(|m| m.len()).sum::<u64>().max(1);
                let mut done = 0u64;
                let mut list = String::new();
                for (i, f) in files.iter().enumerate() {
                    let name = format!("{:03}_{}", i + 1, f.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default());
                    let len = std::fs::copy(f, dest.join(&name)).map_err(|e| format!("Copying {name} failed: {e}"))?;
                    done += len;
                    list.push_str(&name);
                    list.push('\n');
                    let _ = tx.send(Msg::ExportProgress(done as f32 / total as f32));
                    ctx.request_repaint();
                }
                std::fs::write(dest.join("playlist.txt"), list).map_err(|e| e.to_string())?;
                std::fs::write(dest.join("settings.txt"), settings_txt).map_err(|e| e.to_string())?;
                Ok((files.len(), dest))
            })();
            let _ = tx.send(Msg::ExportDone(res));
            ctx.request_repaint();
        });
    }

    /// Apply finished work; returns messages for the activity log (ok, text).
    pub fn poll(&mut self) -> Vec<(bool, String)> {
        let mut out = Vec::new();
        while let Ok(m) = self.rx.try_recv() {
            match m {
                Msg::Prepared { path, out: res } => {
                    if let Some(it) = self.items.iter_mut().find(|i| i.path == path) {
                        it.preparing = false;
                        match res {
                            Ok(p) => {
                                out.push((true, format!("Prepared {}", it.name)));
                                it.prepared = Some(p);
                            }
                            Err(e) => out.push((false, format!("Could not prepare {}: {e}", it.name))),
                        }
                    }
                }
                Msg::ExportProgress(p) => self.exporting = Some(p),
                Msg::ExportDone(r) => {
                    self.exporting = None;
                    match r {
                        Ok((n, d)) => out.push((true, format!("Saved {n} file(s) to {}", d.display()))),
                        Err(e) => out.push((false, e)),
                    }
                }
            }
        }
        out
    }
}

fn no_window(_c: &mut Command) {
    #[cfg(target_os = "windows")]
    {
        use std::os::windows::process::CommandExt;
        _c.creation_flags(0x0800_0000);
    }
}

/// Removable drives (SD cards, USB sticks) currently attached.
pub fn removable_drives() -> Vec<(String, PathBuf, u64)> {
    let Ok(disks) = sysinfo::Disks::new_with_refreshed_list() else { return Vec::new() };
    disks
        .iter()
        .filter(|d| d.is_removable() && d.total_space() > 0)
        .map(|d| {
            let mount = d.mount_point().to_path_buf();
            let name = d.name().to_string_lossy().to_string();
            let label = if name.is_empty() { mount.display().to_string() } else { format!("{name} ({})", mount.display()) };
            (label, mount, d.available_space())
        })
        .collect()
}

pub fn fmt_bytes(b: u64) -> String {
    let units = ["B", "KB", "MB", "GB", "TB"];
    let mut v = b as f64;
    let mut i = 0;
    while v >= 1024.0 && i < units.len() - 1 {
        v /= 1024.0;
        i += 1;
    }
    if i == 0 { format!("{b} B") } else if v >= 100.0 { format!("{v:.0} {}", units[i]) } else { format!("{v:.1} {}", units[i]) }
}

