142	/// The hologram fan preview: a dark disc, the current picture (or a glowing placeholder for
143	/// videos), spinning LED blades and a hub.
144	#[allow(clippy::too_many_arguments)]
145	pub fn fan(painter: &egui::Painter, rect: Rect, p: &Palette, item: Option<&media::Item>, blades: usize, spinning: bool, on: bool, t: f32, brightness: i32) {
146	    let c = rect.center();
147	    let r = rect.width() / 2.0 - 8.0;
148	    for k in 0..6 {
149	        let a = 14 - k * 2;
150	        painter.circle_filled(c, r + 8.0 - k as f32 * 1.5, p.accent.gamma_multiply(a as f32 / 255.0 * if on { 1.0 } else { 0.3 }));
151	    }
152	    painter.circle_filled(c, r, Color32::from_rgb(5, 6, 10));
153	    let lum = 0.45 + 0.055 * brightness as f32;
154	    if on {
155	        match item.and_then(|i| i.thumb.as_ref()) {
156	            Some(tex) => image_circle(painter, tex, c, r - 6.0, lum),
157	            None => {
158	                let hue_a = p.accent;
159	                let hue_b = Color32::from_rgb(56, 189, 248);
160	                for i in 0..5 {
161	                    let rr = r * (0.25 + i as f32 * 0.14);
162	                    let phase = t * (0.8 + i as f32 * 0.25) * if i % 2 == 0 { 1.0 } else { -1.0 };
163	                    let segs = 48;
164	                    let len = 0.55 + 0.1 * i as f32;
165	                    let pts: Vec<Pos2> = (0..=segs)
166	                        .map(|k| {
167	                            let a = phase + std::f32::consts::TAU * len * k as f32 / segs as f32;
168	                            c + vec2(a.cos(), a.sin()) * rr
169	                        })
170	                        .collect();
171	                    let col = mix(hue_a, hue_b, i as f32 / 4.0).gamma_multiply(lum);
172	                    painter.add(egui::Shape::line(pts, Stroke::new(3.0, col)));
173	                }
174	                let label = if item.is_some() { "▶ Video" } else { "No media" };
175	                painter.text(c + vec2(0.0, r * 0.12), Align2::CENTER_CENTER, label, FontId::new(14.0, bold()), Color32::from_gray(220).gamma_multiply(lum));
176	            }
177	        }
178	    }
179	    let n = blades.max(1);
180	    let base = if spinning { t * 9.0 } else { 0.3 };
181	    for b in 0..n {
182	        let a = base + std::f32::consts::TAU * b as f32 / n as f32;
183	        let dir = vec2(a.cos(), a.sin());
184	        let alpha = if spinning { 0.16 } else { 0.5 };
