#[allow(clippy::too_many_arguments)]
pub fn fan(painter: &egui::Painter, rect: Rect, p: &Palette, item: Option<&media::Item>, blades: usize, spinning: bool, on: bool, t: f32, brightness: i32) {
    let c = rect.center();
    let r = rect.width() / 2.0 - 8.0;
    for k in 0..6 {
        let a = 14 - k * 2;
        painter.circle_filled(c, r + 8.0 - k as f32 * 1.5, p.accent.gamma_multiply(a as f32 / 255.0 * if on { 1.0 } else { 0.3 }));
    }
    painter.circle_filled(c, r, Color32::from_rgb(5, 6, 10));
    let lum = 0.45 + 0.055 * brightness as f32;
    if on {
        match item.and_then(|i| i.thumb.as_ref()) {
            Some(tex) => image_circle(painter, tex, c, r - 6.0, lum),
            None => {
                let hue_a = p.accent;
                let hue_b = Color32::from_rgb(56, 189, 248);
                for i in 0..5 {
                    let rr = r * (0.25 + i as f32 * 0.14);
                    let phase = t * (0.8 + i as f32 * 0.25) * if i % 2 == 0 { 1.0 } else { -1.0 };
                    let segs = 48;
                    let len = 0.55 + 0.1 * i as f32;
                    let pts: Vec<Pos2> = (0..=segs)
                        .map(|k| {
                            let a = phase + std::f32::consts::TAU * len * k as f32 / segs as f32;
                            c + vec2(a.cos(), a.sin()) * rr
                        })
                        .collect();
                    let col = mix(hue_a, hue_b, i as f32 / 4.0).gamma_multiply(lum);
                    painter.add(egui::Shape::line(pts, Stroke::new(3.0, col)));
                }
                let label = if item.is_some() { "▶ Video" } else { "No media" };
                painter.text(c + vec2(0.0, r * 0.12), Align2::CENTER_CENTER, label, FontId::new(14.0, bold()), Color32::from_gray(220).gamma_multiply(lum));
            }
        }
    }
    let n = blades.max(1);
    let base = if spinning { t * 9.0 } else { 0.3 };
    for b in 0..n {
        let a = base + std::f32::consts::TAU * b as f32 / n as f32;
        let dir = vec2(a.cos(), a.sin());
        let alpha = if spinning { 0.16 } else { 0.5 };
        painter.line_segment([c + dir * 14.0, c + dir * (r - 4.0)], Stroke::new(if spinning { 6.0 } else { 4.0 }, Color32::from_white_alpha((alpha * 255.0) as u8)));
