impl ColorMode {
    pub const ALL: [ColorMode; 3] = [ColorMode::Colorful, ColorMode::Common, ColorMode::Highlight];
    pub fn label(self) -> &'static str {
        match self {
            ColorMode::Colorful => "Colorful",
            ColorMode::Common => "Common",
