pub fn encode_frame(polar: &[u8], spec: &Spec, curve: &[u8; 256]) -> Vec<u8> {
    let mut px: Vec<u8> = polar.iter().map(|&v| curve[v as usize]).collect();
    thin_hub(&mut px, spec);
