319	/// Like the original, silence from the fan never counts as a lost connection.
320	fn session(mut s: TcpStream, addr: &str, rx: &Receiver<Cmd>, tx: &Sender<Event>, ctx: &egui::Context) -> SessionEnd {
321	    let send = |e: Event| {
322	        let ok = tx.send(e).is_ok();
323	        ctx.request_repaint();
