326	    let _ = s.set_nodelay(true);
327	    let _ = s.set_read_timeout(Some(Duration::from_millis(100)));
328	    let _ = s.set_write_timeout(Some(Duration::from_secs(5)));
329	    if let Err(e) = s.write_all(protocol::HELLO) {
330	        return SessionEnd::Lost(e.to_string());
331	    }
332	    send(Event::Status(Status::Connected));
333	    send(Event::Log(LogKind::Ok, "Connected to the fan. Asking for its settings and file list…".into()));
334	    let mut clock = ClockBuffer::default();
335	    let mut reader = FrameReader::default();
336	    let mut buf = [0u8; 4096];
337	    let mut first_status = true;
338	    loop {
