350	                        if let Err(e) = s.write_all(&frame) {
351	                            return SessionEnd::Lost(e.to_string());
352	                        }
353	                    }
354	                }
355	                Err(TryRecvError::Empty) => break,
356	                Err(TryRecvError::Disconnected) => return SessionEnd::Stopped,
357	            }
